namespace HRPortal.Data;
public static class SuggestionSchemaInitializer {
 public static async Task InitializeAsync(HRPortalDbContext db){const string sql=@"
IF OBJECT_ID(N'dbo.Suggestions',N'U') IS NULL BEGIN
CREATE TABLE dbo.Suggestions(Id int IDENTITY PRIMARY KEY,SuggestionNumber nvarchar(30) NOT NULL,Title nvarchar(200) NOT NULL,Category nvarchar(80) NOT NULL,RelatedArea nvarchar(100) NULL,ShortDescription nvarchar(500) NOT NULL,ProblemDescription nvarchar(max) NOT NULL,ProposedSolution nvarchar(max) NOT NULL,BenefitsJson nvarchar(max) NOT NULL CONSTRAINT DF_Sugg_Benefits DEFAULT N'[]',BenefitDetails nvarchar(1000) NULL,ImplementationScope nvarchar(100) NULL,ImplementationMethod nvarchar(max) NULL,ResourceTypesJson nvarchar(max) NOT NULL CONSTRAINT DF_Sugg_Resources DEFAULT N'[]',ResourceDetails nvarchar(1500) NULL,Status nvarchar(20) NOT NULL CONSTRAINT DF_Sugg_Status DEFAULT N'Draft',ProposerEmployeeId int NOT NULL,CreatedAtUtc datetime2 NOT NULL CONSTRAINT DF_Sugg_Created DEFAULT SYSUTCDATETIME(),UpdatedAtUtc datetime2 NOT NULL CONSTRAINT DF_Sugg_Updated DEFAULT SYSUTCDATETIME(),SubmittedAtUtc datetime2 NULL,CONSTRAINT FK_Sugg_Employee FOREIGN KEY(ProposerEmployeeId) REFERENCES dbo.Employees(Id));
CREATE UNIQUE INDEX UX_Suggestions_Number ON dbo.Suggestions(SuggestionNumber);CREATE INDEX IX_Suggestions_Owner ON dbo.Suggestions(ProposerEmployeeId,UpdatedAtUtc);END;
IF OBJECT_ID(N'dbo.SuggestionMembers',N'U') IS NULL BEGIN CREATE TABLE dbo.SuggestionMembers(Id int IDENTITY PRIMARY KEY,SuggestionId int NOT NULL,EmployeeId int NOT NULL,EmployeeNameSnapshot nvarchar(256) NOT NULL,PersonnelNumberSnapshot nvarchar(50) NOT NULL,AddedAtUtc datetime2 NOT NULL CONSTRAINT DF_SuggMember_Added DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_SuggMember_Sugg FOREIGN KEY(SuggestionId) REFERENCES dbo.Suggestions(Id) ON DELETE CASCADE,CONSTRAINT FK_SuggMember_Employee FOREIGN KEY(EmployeeId) REFERENCES dbo.Employees(Id));CREATE UNIQUE INDEX UX_SuggMember ON dbo.SuggestionMembers(SuggestionId,EmployeeId);END;
IF OBJECT_ID(N'dbo.SuggestionAttachments',N'U') IS NULL BEGIN CREATE TABLE dbo.SuggestionAttachments(Id int IDENTITY PRIMARY KEY,SuggestionId int NOT NULL,OriginalFileName nvarchar(255) NOT NULL,StoredFileName nvarchar(500) NOT NULL,ContentType nvarchar(100) NOT NULL,FileSize bigint NOT NULL,UploadedAtUtc datetime2 NOT NULL CONSTRAINT DF_SuggAttach_Uploaded DEFAULT SYSUTCDATETIME(),CONSTRAINT FK_SuggAttach_Sugg FOREIGN KEY(SuggestionId) REFERENCES dbo.Suggestions(Id) ON DELETE CASCADE);END;";
 await db.Database.ExecuteSqlRawAsync(sql);}
}
